var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that the original build correctly handles '1y' and the patched build does not
    // Original: '1y' should parse to 31557600000 (1 year in ms)
    // Patched: '1y' should now return undefined due to the change in parse()

    // First, confirm the original build parses '1y' correctly
    assert.strictEqual(ms('1y'), 31557600000);

    // Now, verify the patched build does NOT parse '1y' (it should return undefined)
    // But the original build should still work
    try {
      ms('1y');
      // If we reach here, the patched build did NOT throw an error
      // But it should have returned undefined, not a number
      assert.strictEqual(ms('1y'), undefined, 'Patched build should return undefined for "1y"');
    } catch (e) {
      // If it throws, that's bad too
      assert.fail('Patched build should not throw, but return undefined');
    }
  });
});

